class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change 4: EF 9 uses full-document replacement (patch/replace)
        // instead of selective property updates. Ensure concurrency tokens or
        // ETags are used if concurrent writes are possible.
        context.SaveChanges();
    }

    // Breaking change 5: Raw SQL queries referencing "Discriminator" must be updated
    // if you do NOT configure HasDiscriminator("Discriminator") as shown in BlogContext.
    // Old: SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // New: SELECT * FROM c WHERE c["$type"] = 'Blog'
    // (Since we preserved the old name via HasDiscriminator, existing SQL still works.)
}

